#!/usr/bin/env python3
"""Generate native catalog data, strings and backend cue titles. Run from any directory."""
import json,pathlib,html
root=pathlib.Path(__file__).resolve().parents[1]
c=json.loads((root/'shared/stretch/catalog.json').read_text())
ids=[m['id'] for m in c['movements']]
assert len(ids)==len(set(ids)), 'Duplicate movement IDs'
assert len(c['templates'])==len({t['id'] for t in c['templates']}), 'Duplicate template IDs'
for m in c['movements']:
    assert m['paths'] or m.get('artwork'), m['id']
    assert all(len(line)>=2 for line in m['paths']), m['id']
    assert all(0<=coordinate<=100 for line in m['paths'] for point in line for coordinate in point), m['id']
    if m.get('artwork'):
        assert (root/'shared/stretch/illustrations'/f'{m["id"]}.svg').is_file(), m['id']
        assert m.get('artworkSide','left') in ['left','right'], m['id']
    assert not m.get('alternating') or (m.get('dynamic') and not m['bilateral']), m['id']
    assert set(m['title'])==set(m['instruction'])=={'en','es','zh-Hans'}, m['id']
for t in c['templates']:
    assert t['entries'] and len(t['entries'])==len({e['movementID'] for e in t['entries']}), t['id']
    assert all(e['movementID'] in ids and e['seconds'] in [15,20,25,30] for e in t['entries']), t['id']
    assert len({m.get('dynamic',False) for m in c['movements'] if m['id'] in [e['movementID'] for e in t['entries']]}) == 1, t['id']
def q(v): return json.dumps(v,ensure_ascii=False)
def write(p,s): (root/p).write_text(s)
sw=['// Generated by scripts/generate-stretch-catalog.py; edit shared/stretch/catalog.json.','import Foundation','enum StretchCatalogData {','    static let definitions: [StretchDefinition] = [']
kt=['// Generated by scripts/generate-stretch-catalog.py; edit shared/stretch/catalog.json.','package com.plainstride.outbound.feature.recording','internal object StretchCatalogData {','    val definitions = listOf(']
translations={}
for m in c['movements']:
    id=m['id']; paths=m['paths']; coords='['+', '.join('['+', '.join(f'CGPoint(x: {x}, y: {y})' for x,y in line)+']' for line in paths)+']'
    sw.append(f'        StretchDefinition(id: {q(id)}, bilateral: {str(m["bilateral"]).lower()}, floor: {str(m["floor"]).lower()}, support: {str(m["support"]).lower()}, surface: {str(m["surface"]).lower()}, area: {q(m["area"])}, lying: {str(m["lying"]).lower()}, paths: {coords}, dynamic: {str(m.get("dynamic",False)).lower()}, artwork: {q(m["artwork"]) if m.get("artwork") else "nil"}, artworkSide: {q(m.get("artworkSide","left"))}, alternating: {str(m.get("alternating",False)).lower()}, cushion: {str(m.get("cushion",False)).lower()}),')
    kp='listOf('+', '.join('listOf('+', '.join(f'{x}f to {y}f' for x,y in line)+')' for line in paths)+')'
    kt.append(f'        StretchDefinition({q(id)}, R.string.stretch_catalog_{id}_title, R.string.stretch_catalog_{id}_instruction, '+', '.join(str(m[k]).lower() for k in ['bilateral','floor','support','surface'])+f', {q(m["area"])}, {str(m["lying"]).lower()}, {kp}, {str(m.get("dynamic",False)).lower()}, {"R.drawable."+m["artwork"] if m.get("artwork") else "null"}, {q(m.get("artworkSide","left"))}, {str(m.get("alternating",False)).lower()}, {str(m.get("cushion",False)).lower()}),')
    for field in ['title','instruction']: translations[f'movement.{id}.{field}']=m[field]
sw+=['    ]','    static let templates: [StretchTemplate] = [']; kt+=['    )','    val templates = listOf(']
for t in c['templates']:
    se=', '.join(f'StretchEntry(movementID: {q(e["movementID"])}, seconds: {e["seconds"]})' for e in t['entries'])
    ke=', '.join(f'StretchEntry({q(e["movementID"])}, {e["seconds"]})' for e in t['entries'])
    sw.append(f'        StretchTemplate(id: {q(t["id"])}, wireSuffix: {q(t["wireSuffix"])}, entries: [{se}]),')
    kt.append(f'        StretchTemplate({q(t["id"])}, R.string.stretch_catalog_template_{t["id"]}, {q(t["wireSuffix"])}, listOf({ke})),')
    translations['template.'+t['id']]=t['title']
sw+=['    ]','}']; kt+=['    )','}']
write('ios/Outbound/Outbound/Activity/StretchCatalogData.swift','\n'.join(sw)+'\n')
write('android/feature/recording/src/main/kotlin/com/plainstride/outbound/feature/recording/StretchCatalogData.kt','\n'.join(kt)+'\n')
translations.update({'ui.'+k:v for k,v in c['ui'].items()})
xc={'sourceLanguage':'en','strings':{},'version':'1.0'}
for k,v in translations.items(): xc['strings']['stretch.catalog.'+k]={'localizations':{l:{'stringUnit':{'state':'translated','value':s}} for l,s in v.items()}}
write('ios/Outbound/Outbound/StretchCatalog.xcstrings',json.dumps(xc,ensure_ascii=False,indent=2)+'\n')
for locale,folder in [('en','values'),('es','values-es'),('zh-Hans','values-zh-rCN')]:
    lines=['<?xml version="1.0" encoding="utf-8"?>','<!-- Generated by scripts/generate-stretch-catalog.py -->','<resources>']
    for k,v in translations.items():
        parts=k.split('.'); name='stretch_catalog_'+ ('_'.join(parts[1:]) if parts[0]=='movement' else '_'.join(parts))
        val=html.escape(v[locale],quote=False).replace("'","\\'")
        lines.append(f'    <string name="{name}">{val}</string>')
    write(f'android/feature/recording/src/main/res/{folder}/stretch_catalog.xml','\n'.join(lines+['</resources>'])+'\n')
titles={m['id']:m.get('audioTitle',m['title']) for m in c['movements']}
write('backend/src/services/liveCoach/stretchCatalogData.ts','// Generated by scripts/generate-stretch-catalog.py.\nexport const stretchMovementTitles = '+json.dumps(titles,ensure_ascii=False,indent=2)+' as const;\n')
write('backend/src/services/liveCoach/stretchCatalogModes.ts', '// Generated by scripts/generate-stretch-catalog.py.\nexport const stretchMovementModes = '+json.dumps({m['id']:{'bilateral':m['bilateral'],'dynamic':m.get('dynamic',False),'alternating':m.get('alternating',False)} for m in c['movements']},indent=2)+' as const;\nexport const stretchTemplateModes = '+json.dumps({t['id']:any(next(m for m in c['movements'] if m['id']==e['movementID']).get('dynamic',False) for e in t['entries']) for t in c['templates']},indent=2)+' as const;\n')
print(f'Generated {len(c["movements"])} movements and {len(c["templates"])} templates.')
